-- Produktionsschema för Supabase/PostgreSQL. Kör först när ett separat Supabase-projekt skapats.
create extension if not exists pgcrypto;
create table public.sources(id uuid primary key default gen_random_uuid(),title text not null,publisher text,publication_year integer,edition text,isbn text,source_type text not null,url text,rights_note text,created_at timestamptz not null default now());
create table public.plants(id uuid primary key default gen_random_uuid(),accepted_scientific_name text not null,taxon_rank text not null default 'species',swedish_name text,category text,lifecycle text,editorial_status text not null default 'draft',intro text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(accepted_scientific_name,taxon_rank));
create table public.plant_names(id uuid primary key default gen_random_uuid(),plant_id uuid not null references public.plants(id) on delete cascade,name text not null,language_code text not null default 'sv',name_type text not null default 'common',source_id uuid references public.sources(id));
create table public.source_claims(id uuid primary key default gen_random_uuid(),source_id uuid not null references public.sources(id),chapter_or_heading text,printed_page text,pdf_page integer,claim_note text not null,short_quote text,access_date date,checked_by text,checked_at timestamptz,verification_status text not null default 'unverified');
create table public.plant_facts(id uuid primary key default gen_random_uuid(),plant_id uuid not null references public.plants(id) on delete cascade,field_key text not null,value_text text,value_numeric numeric,unit text,context_region text,context_note text,source_claim_id uuid references public.source_claims(id),confidence text not null default 'unverified',created_at timestamptz not null default now());
create table public.cultivars(id uuid primary key default gen_random_uuid(),parent_plant_id uuid not null references public.plants(id) on delete cascade,cultivar_name text not null,plant_breeders_rights_note text,notes text,unique(parent_plant_id,cultivar_name));
create table public.images(id uuid primary key default gen_random_uuid(),plant_id uuid not null references public.plants(id) on delete cascade,storage_path text,source_url text,creator text,licence text,attribution text,permission_note text,created_at timestamptz not null default now());
alter table public.plants enable row level security;alter table public.sources enable row level security;alter table public.plant_names enable row level security;alter table public.source_claims enable row level security;alter table public.plant_facts enable row level security;alter table public.cultivars enable row level security;alter table public.images enable row level security;
-- Lägg till SELECT-policy för publicerade poster och redaktörspolicyer efter att admin-roll och auth-flöde definierats. Inga öppna skrivpolicyer ingår.
